NODE
);repository=${values[0]};token=${values[1]};outbox=${values[2]};allowed=${values[3]};signer=${values[4]};ledger_allowed=${values[5]};ledger_signer=${values[6]};state_dir=${values[7]};state_key=${values[8]};state_allowed=${values[9]};state_signer=${values[10]};deployment_id=${values[11]};nonce=${values[12]};receipt_root="$outbox/receipts/$nonce";[[ -d $receipt_root && ! -L $receipt_root && -L $receipt_root/current ]]||exit 1;receipt_generation=$(realpath "$receipt_root/current");[[ $receipt_generation == "$receipt_root/"* ]]||exit 1;receipt="$receipt_generation/payload.json";receipt_sig="$receipt.sig";ledger_root="$outbox/deployment-ledger";tmpdir=$(mktemp -d);trap 'rm -rf "$tmpdir"' EXIT
