NODE
then head=$(node -p 'require(process.argv[1]).head.payloadPath' "$tmpdir/state-chain.json");bound_runtime=$(node -p 'require(process.argv[1]).head.payload.runtimeReleasePath' "$tmpdir/state-chain.json");[[ $bound_runtime == "$runtime" && -d $runtime && ! -L $runtime ]]||exit 1;ln -sfn "generations/$(basename "$(dirname "$head")")" "$state_dir/current.next";mv -Tf "$state_dir/current.next" "$state_dir/current";ln -sfn "$runtime" /opt/steam-top/current.next;mv -Tf /opt/steam-top/current.next /opt/steam-top/current;if [[ -z $activation ]];then activation_generation=$(mktemp -d "$activations/.generation.XXXXXX");activation="$activation_generation/payload.json";node - "$activation" "$deployment_id" "$nonce" "$tmpdir/state-chain.json" "$state_signer" <<'NODE'
