NODE
emit_activation;exit 0;fi;generation=$(mktemp -d "$generations/.generation.XXXXXX");tmp="$generation/payload.json";PRODUCTION_STATE_SIGNER_ID="$state_signer" node - "$bundle" "$receipt" "$ledger" "$tmpdir/state-chain.json" "$tmp" <<'NODE'
